def find_max(words):
    if not words:
        return ""

    def count_unique_chars(word):
        return len(set(word))

    max_word = max(words, key=count_unique_chars)

    # In case of a tie, choose the lexicographically smaller word
    max_word_count = count_unique_chars(max_word)
    for word in sorted(words):
        if count_unique_chars(word) == max_word_count:
            max_word = word
            break

    return max_word
```

